/**
 * Other tools' comments through the HTML save path (spec 024 024-FR-023,
 * 024-AC-031): the writer puts a new block before a directive run, and
 * refuses a target inside a generated START/END region with its own reason –
 * `generated-region`, which the window words "This part is generated by a
 * tool" – writing nothing.
 */
import { afterEach, beforeEach, describe, expect, it } from 'vitest'
import { ErrorCode } from '../../../shared/errors'
import {
  VIEW,
  byId,
  draftFor,
  makeProject,
  makeWriter,
  okBlock,
  snapshot,
  type TempProject
} from '../preview/comments/__test-helpers__/commentWriterHarness'

const REGION_PAGE = [
  '<!doctype html>',
  '<html><body>',
  '  <!-- prettier-ignore -->',
  '  <table id="grid"><tr><td>a</td></tr></table>',
  '  <!-- START doctoc generated TOC please keep comment here to allow auto update -->',
  '  <ul>',
  '    <li id="two"><a href="#two">Two</a></li>',
  '  </ul>',
  '  <!-- END doctoc generated TOC please keep comment here to allow auto update -->',
  '  <p id="after">After the region.</p>',
  '</body></html>',
  ''
].join('\n')

let project: TempProject

beforeEach(async () => {
  project = await makeProject()
  await project.write('index.html', REGION_PAGE)
})

afterEach(async () => {
  await project.dispose()
})

async function addOn(id: string) {
  const { writer } = makeWriter()
  const bytes = await project.read('index.html')
  return writer.add({ file: project.target('index.html'), draft: draftFor(bytes, byId(id)), view: VIEW, text: 'Check this.' })
}

describe('024-AC-031 other tools\' comments on the HTML save path', () => {
  it('024-AC-031 a comment on the table lands before the prettier-ignore directive, which stays next to its table', async () => {
    const result = await addOn('grid')
    if (!result.ok || result.threadId === null) throw new Error(`refused: ${JSON.stringify(result)}`)
    const after = (await project.read('index.html')).toString('utf8')
    expect(after.indexOf(result.threadId)).toBeLessThan(after.indexOf('prettier-ignore'))
    expect(after).toContain('<!-- prettier-ignore -->\n  <table id="grid">')
    expect(okBlock(await project.read('index.html'), result.threadId).target).toMatchObject({ state: 'attached' })
  })

  it('024-AC-031 a comment on the paragraph after the region lands after the END comment', async () => {
    const result = await addOn('after')
    if (!result.ok || result.threadId === null) throw new Error(`refused: ${JSON.stringify(result)}`)
    const after = (await project.read('index.html')).toString('utf8')
    expect(after.indexOf('END doctoc')).toBeLessThan(after.indexOf(result.threadId))
  })

  it('024-AC-031 a comment on a list item inside the region is refused as generated-region and writes nothing', async () => {
    const before = await snapshot(project.path('index.html'))

    const result = await addOn('two')

    expect(result).toEqual({ ok: false, code: ErrorCode.COMMENT_TARGET_MOVED, reason: 'generated-region' })
    expect(await snapshot(project.path('index.html'))).toEqual(before)
  })
})
